questionvariables.text:
/* Six true statements 'if A, then B': [vnum, statement, A, B, direct, contrapositive, contradiction, converse, inverse, best route]. */
vbank: [
 [1, "Let \\(n\\) be an integer. If \\(n\\) is odd, then \\(n^3 + 1\\) is even.", "\\(n\\) is odd", "\\(n^3 + 1\\) is even", "Suppose that \\(n\\) is odd, so \\(n = 2k + 1\\) for some integer \\(k\\). We show that \\(n^3 + 1\\) is even.", "Suppose that \\(n^3 + 1\\) is odd. We show that \\(n\\) is even.", "Suppose that \\(n\\) is odd and that \\(n^3 + 1\\) is odd. We look for a contradiction.", "Suppose that \\(n^3 + 1\\) is even. We show that \\(n\\) is odd.", "Suppose that \\(n\\) is even. We show that \\(n^3 + 1\\) is odd.", "Here the direct proof is the natural one: \\(n = 2k + 1\\) gives \\(n^3 + 1 = 2(4k^3 + 6k^2 + 3k + 1)\\)."],
 [2, "Let \\(n\\) be an integer. If \\(n^2\\) is odd, then \\(n\\) is odd.", "\\(n^2\\) is odd", "\\(n\\) is odd", "Suppose that \\(n^2\\) is odd, so \\(n^2 = 2k + 1\\) for some integer \\(k\\). We show that \\(n\\) is odd.", "Suppose that \\(n\\) is even, so \\(n = 2k\\) for some integer \\(k\\). We show that \\(n^2\\) is even.", "Suppose that \\(n^2\\) is odd and that \\(n\\) is even. We look for a contradiction.", "Suppose that \\(n\\) is odd. We show that \\(n^2\\) is odd.", "Suppose that \\(n^2\\) is even. We show that \\(n\\) is even.", "Here the contrapositive is easiest: \\(n = 2k\\) gives \\(n^2 = 2(2k^2)\\). Starting from \\(n^2 = 2k + 1\\) tells you little about \\(n\\)."],
 [3, "Let \\(n\\) be an integer. If \\(3n + 2\\) is odd, then \\(n\\) is odd.", "\\(3n + 2\\) is odd", "\\(n\\) is odd", "Suppose that \\(3n + 2\\) is odd, so \\(3n + 2 = 2k + 1\\) for some integer \\(k\\). We show that \\(n\\) is odd.", "Suppose that \\(n\\) is even, so \\(n = 2k\\) for some integer \\(k\\). We show that \\(3n + 2\\) is even.", "Suppose that \\(3n + 2\\) is odd and that \\(n\\) is even. We look for a contradiction.", "Suppose that \\(n\\) is odd. We show that \\(3n + 2\\) is odd.", "Suppose that \\(3n + 2\\) is even. We show that \\(n\\) is even.", "Here the contrapositive is easiest: \\(n = 2k\\) gives \\(3n + 2 = 2(3k + 1)\\)."],
 [4, "Let \\(x\\) be a real number. If \\(x\\) is irrational, then \\(x + 1\\) is irrational.", "\\(x\\) is irrational", "\\(x + 1\\) is irrational", "Suppose that \\(x\\) is irrational. We show that \\(x + 1\\) is irrational.", "Suppose that \\(x + 1\\) is rational, so \\(x + 1 = \\dfrac{a}{b}\\) for some integers \\(a\\) and \\(b\\) with \\(b \\neq 0\\). We show that \\(x\\) is rational.", "Suppose that \\(x\\) is irrational and that \\(x + 1\\) is rational. We look for a contradiction.", "Suppose that \\(x + 1\\) is irrational. We show that \\(x\\) is irrational.", "Suppose that \\(x\\) is rational. We show that \\(x + 1\\) is rational.", "Here ‘\\(x\\) is irrational’ gives nothing to calculate with, so the contrapositive (or a contradiction) is the natural route: \\(x + 1 = \\dfrac{a}{b}\\) gives \\(x = \\dfrac{a - b}{b}\\), which is rational."],
 [5, "Let \\(a\\) and \\(b\\) be integers. If \\(ab\\) is even, then \\(a\\) is even or \\(b\\) is even.", "\\(ab\\) is even", "\\(a\\) is even or \\(b\\) is even", "Suppose that \\(ab\\) is even, so \\(ab = 2k\\) for some integer \\(k\\). We show that \\(a\\) is even or \\(b\\) is even.", "Suppose that \\(a\\) and \\(b\\) are both odd. We show that \\(ab\\) is odd.", "Suppose that \\(ab\\) is even and that \\(a\\) and \\(b\\) are both odd. We look for a contradiction.", "Suppose that \\(a\\) is even or \\(b\\) is even. We show that \\(ab\\) is even.", "Suppose that \\(ab\\) is odd. We show that \\(a\\) and \\(b\\) are both odd.", "Here the contrapositive is natural: \\(a = 2k + 1\\) and \\(b = 2l + 1\\) give \\(ab = 2(2kl + k + l) + 1\\). The opposite of ‘\\(a\\) is even or \\(b\\) is even’ is ‘\\(a\\) and \\(b\\) are both odd’."],
 [6, "Let \\(n\\) be an integer. If \\(n\\) is a multiple of 6, then \\(n\\) is a multiple of 3.", "\\(n\\) is a multiple of 6", "\\(n\\) is a multiple of 3", "Suppose that \\(n\\) is a multiple of 6, so \\(n = 6k\\) for some integer \\(k\\). We show that \\(n\\) is a multiple of 3.", "Suppose that \\(n\\) is not a multiple of 3. We show that \\(n\\) is not a multiple of 6.", "Suppose that \\(n\\) is a multiple of 6 and that \\(n\\) is not a multiple of 3. We look for a contradiction.", "Suppose that \\(n\\) is a multiple of 3. We show that \\(n\\) is a multiple of 6.", "Suppose that \\(n\\) is not a multiple of 6. We show that \\(n\\) is not a multiple of 3.", "Here the direct proof is immediate: \\(n = 6k = 3(2k)\\). The converse and ‘if not A, then not B’ are false here (take \\(n = 3\\)), so proofs of them could never be finished."]
];
vrec: rand(vbank);
vnum: vrec[1]; stmt: vrec[2]; Atext: vrec[3]; Btext: vrec[4];
ldir: vrec[5]; lcp: vrec[6]; lcon: vrec[7]; lconv: vrec[8]; linv: vrec[9]; best: vrec[10];
/* Rows [type, line, correct, likely error, other wrong option]. */
rowsall: [[rdir, ldir, fdir, fcon, foth], [rcp, lcp, fcp, fcon, fdir], [rcon, lcon, fcon, fcp, fdir], [rconv, lconv, foth, fdir, fcp], [rinv, linv, foth, fcp, fcon]];
qrows: random_permutation(rowsall);
expl(t) := if t = rdir then "This line assumes A and aims for B: a direct proof." else if t = rcp then "This line assumes not B and aims for not A. It proves the contrapositive, ‘if not B, then not A’, which is true exactly when the statement is." else if t = rcon then "This line assumes A and not B together and looks for something impossible: a proof by contradiction." else if t = rconv then "This line assumes B and aims for A. It proves the converse, ‘if B, then A’, which is a different statement." else if t = rinv then "This line assumes not A and aims for not B. It proves ‘if not A, then not B’, which is a different statement." else "";
/* Wrong-answer feedback says why the chosen kind does not fit and never names the right kind. leaddiag: the likely confusion for each kind of line. kindsays: any other wrong choice, by the option chosen. */
leaddiag(t) := if t = rdir then "A proof by contradiction assumes two things together, A and not B, and looks for something impossible. Count the things this line assumes, and look at what it aims for." else if t = rcp then "A proof by contradiction assumes A and not B together, and looks for something impossible. Does this line assume A? Look at what it sets out to show." else if t = rcon then "A proof of the contrapositive assumes only not B, and aims to show not A. This line assumes more than that. Look at everything it assumes, and at what it is looking for." else if t = rconv then "A direct proof starts from A, the ‘if’ part, and aims for B. Check which part this line starts from: starting from what you want to prove is a common slip." else if t = rinv then "The contrapositive swaps the two parts as well as negating them: ‘if not B, then not A’. Check which part this line assumes and which part it aims for." else "";
kindsays(c) := if c = fdir then "A direct proof assumes A and aims for B. Compare that with what this line assumes and what it aims for." else if c = fcp then "A proof of the contrapositive assumes not B and aims for not A. Compare that with what this line assumes and what it aims for." else if c = fcon then "A proof by contradiction assumes A and not B together and looks for something impossible. Compare that with what this line assumes and what it aims for." else "This line does start a proof of the statement itself. Decide which of A, B, not A and not B it assumes, and what it aims for.";
opts(c) := [[fdir, is(c = fdir), "direct proof"], [fcp, is(c = fcp), "proof of the contrapositive"], [fcon, is(c = fcon), "proof by contradiction"], [foth, is(c = foth), "proof of a different statement"]];
typ1: qrows[1][1]; txt1: qrows[1][2]; cor1: qrows[1][3]; diag1: qrows[1][4]; oth1: qrows[1][5];
ta1: opts(cor1); expl1: expl(typ1); lead1: leaddiag(typ1);
typ2: qrows[2][1]; txt2: qrows[2][2]; cor2: qrows[2][3]; diag2: qrows[2][4]; oth2: qrows[2][5];
ta2: opts(cor2); expl2: expl(typ2); lead2: leaddiag(typ2);
typ3: qrows[3][1]; txt3: qrows[3][2]; cor3: qrows[3][3]; diag3: qrows[3][4]; oth3: qrows[3][5];
ta3: opts(cor3); expl3: expl(typ3); lead3: leaddiag(typ3);
typ4: qrows[4][1]; txt4: qrows[4][2]; cor4: qrows[4][3]; diag4: qrows[4][4]; oth4: qrows[4][5];
ta4: opts(cor4); expl4: expl(typ4); lead4: leaddiag(typ4);
typ5: qrows[5][1]; txt5: qrows[5][2]; cor5: qrows[5][3]; diag5: qrows[5][4]; oth5: qrows[5][5];
ta5: opts(cor5); expl5: expl(typ5); lead5: leaddiag(typ5);
s_assert(every(lambda([rw], is(length(unique([rw[3], rw[4], rw[5]])) = 3)), qrows), true);
